<script setup lang="ts">
import { Mail, ArrowRight, LogOut } from 'lucide-vue-next'
const app=useApp();const config=useRuntimeConfig();const email=ref('');const message=ref('');const busy=ref(false);const deleting=ref(false);const confirmation=ref('')
async function login(){busy.value=true;message.value='';try{const c=app.auth();if(!c){message.value='ログインにはSupabaseの設定が必要です。デモはログインなしで利用できます。';return}const {error}=await c.auth.signInWithOtp({email:email.value,options:{emailRedirectTo:`${config.public.siteUrl}/account`}});if(error)throw error;message.value='ログイン用リンクをメールで送りました。この端末でリンクを開いてください。'}catch{message.value='メールを送信できませんでした。入力内容を確認して、しばらくしてからお試しください。'}finally{busy.value=false}}
async function remove(){if(confirmation.value!=='退会する')return;busy.value=true;try{await app.api('/api/account',{method:'DELETE'});await app.signOut();for(const key of Object.keys(localStorage))if(key.startsWith('hitokuchi:'))localStorage.removeItem(key);message.value='アカウントと個人履歴を削除しました。';deleting.value=false}catch{message.value='退会できませんでした。時間をおいて再度お試しください。'}finally{busy.value=false}}
useHead({title:'マイページ | ひとくち大阪',meta:[{name:'robots',content:'noindex'}]})
</script>
<template><section class="page auth-page"><div class="center-heading"><div class="eyebrow">YOUR OWN FOOD DISCOVERY</div><h1>{{app.email.value?'マイページ':'おいしい記録を、持ち歩こう。'}}</h1><p>気になるお店も、食べた記録も。<br>ログインすると、ほかの端末でも続きから。</p></div><div class="panel"><ClientOnly><template v-if="app.email.value"><p>{{app.email.value}}</p><p class="muted">保存やアンケートは、このアカウントに同期されます。</p><NuxtLink v-if="app.isAdmin.value" to="/admin" class="button primary">管理画面へ</NuxtLink><button class="button secondary" @click="app.signOut"><LogOut :size="16"/>ログアウト</button><button class="text-link danger-link" @click="deleting=!deleting">アカウントを削除する</button><div v-if="deleting" class="delete-box"><p>保存・訪問・アンケートを含む個人履歴を削除します。元に戻せません。</p><label class="field">確認のため「退会する」と入力<input v-model="confirmation"/></label><button class="button secondary" :disabled="confirmation!=='退会する'||busy" @click="remove">退会を確定する</button></div></template><form v-else @submit.prevent="login"><label class="field">メールアドレス<div class="input-icon"><Mail :size="18"/><input v-model="email" type="email" autocomplete="email" required placeholder="you@example.com"/></div></label><button class="button primary full" :disabled="busy" type="submit">{{busy?'送信中…':'ログインリンクを受け取る'}}<ArrowRight :size="18"/></button><p class="muted">パスワードは不要です。メール内のリンクからログインできます。</p></form></ClientOnly><p v-if="message" class="notice" role="status">{{message}}</p></div><NuxtLink to="/" class="text-link centered">ログインせずにお店を見つける →</NuxtLink></section></template>
